  }
  #durum {
    font-size: 20px;
    margin-top: 15px;
  }
  button {
    margin-top: 15px;
    padding: 8px 16px;
    font-size: 16px;
    cursor: pointer;
  }
</style>
</head>
<body>
<h1>Tic-Tac-Toe</h1>
<canvas id="oyunAlani" width="300" height="300"></canvas>
<div id="durum"></div>
<button id="yenidenBaslat">Yeniden Başlat</button>

<script src="logic.js"></script>
<script>
  const canvas = document.getElementById('oyunAlani');
  const ctx = canvas.getContext('2d');
  const durumEl = document.getElementById('durum');
  const yenidenBaslatBtn = document.getElementById('yenidenBaslat');

  const HUCRE_BOYU = 100;
  let tahta = yeniOyun();
  let oyunBitti = false;

  function ciz() {
    ctx.clearRect(0, 0, canvas.width, canvas.height);

    ctx.strokeStyle = '#888';
    ctx.lineWidth = 2;
    for (let i = 1; i < 3; i++) {
      ctx.beginPath();
      ctx.moveTo(i * HUCRE_BOYU, 0);
      ctx.lineTo(i * HUCRE_BOYU, canvas.height);
      ctx.stroke();

      ctx.beginPath();
      ctx.moveTo(0, i * HUCRE_BOYU);
      ctx.lineTo(canvas.width, i * HUCRE_BOYU);
      ctx.stroke();
    }

    ctx.font = '48px sans-serif';
    ctx.textAlign = 'center';
    ctx.textBaseline = 'middle';

    for (let i = 0; i < 9; i++) {
      const isaret = tahta[i];
      if (isaret) {
        const satir = Math.floor(i / 3);
        const sutun = i % 3;
        const x = sutun * HUCRE_BOYU + HUCRE_BOYU / 2;
        const y = satir * HUCRE_BOYU + HUCRE_BOYU / 2;
        ctx.fillStyle = isaret === 'X' ? '#4da6ff' : '#ff6b6b';
        ctx.fillText(isaret, x, y);
      }
    }
  }

  function durumGuncelle() {
    const kazananIsaret = kazanan(tahta);
    if (kazananIsaret) {
      durumEl.textContent = kazananIsaret + ' kazandı!';
      oyunBitti = true;
    } else if (beraberlikMi(tahta)) {
      durumEl.textContent = 'Berabere!';
      oyunBitti = true;
    } else {
      durumEl.textContent = 'Sıra: ' + siradakiOyuncu(tahta);
      oyunBitti = false;
    }
  }

  canvas.addEventListener('click', (e) => {
    if (oyunBitti) return;

    const rect = canvas.getBoundingClientRect();
    const x = e.clientX - rect.left;
    const y = e.clientY - rect.top;
    const sutun = Math.floor(x / HUCRE_BOYU);
    const satir = Math.floor(y / HUCRE_BOYU);
    const indeks = satir * 3 + sutun;

    const isaret = siradakiOyuncu(tahta);
    const basarili = hamleYap(tahta, indeks, isaret);
    if (basarili) {
      ciz();
      durumGuncelle();
    }
  });

  yenidenBaslatBtn.addEventListener('click', () => {
    tahta = yeniOyun();
    oyunBitti = false;
    ciz();
    durumGuncelle();
  });

  ciz();
  durumGuncelle();
</script>
</body>
</html>

