### logic.js
```
function yeniOyun() {
  return Array(9).fill(null);
}

function hamleYap(tahta, indeks, isaret) {
  if (typeof indeks !== 'number' || indeks < 0 || indeks > 8) {
    return false;
  }
  if (tahta[indeks] !== null) {
    return false;
  }
  tahta[indeks] = isaret;
  return true;
}

function siradakiOyuncu(tahta) {
  let xSayisi = 0;
  let oSayisi = 0;
  for (let i = 0; i < tahta.length; i++) {
    if (tahta[i] === 'X') xSayisi++;
    else if (tahta[i] === 'O') oSayisi++;
  }
  return xSayisi > oSayisi ? 'O' : 'X';
}

function kazanan(tahta) {
  const kombinasyonlar = [
    [0, 1, 2],
    [3, 4, 5],
    [6, 7, 8],
    [0, 3, 6],
    [1, 4, 7],
    [2, 5, 8],
    [0, 4, 8],
    [2, 4, 6]
  ];
  for (const [a, b, c] of kombinasyonlar) {
    if (tahta[a] !== null && tahta[a] === tahta[b] && tahta[b] === tahta[c]) {
      return tahta[a];
    }
  }
  return null;
}

function beraberlikMi(tahta) {
  const dolu = tahta.every((hucre) => hucre !== null);
  return dolu && kazanan(tahta) === null;
}

if (typeof module !== 'undefined' && module.exports) {
  module.exports = { yeniOyun, hamleYap, siradakiOyuncu, kazanan, beraberlikMi };
}

