const { test } = require('node:test');
const assert = require('node:assert/strict');
const { yeniOyun, hamleYap, siradakiOyuncu, kazanan, beraberlikMi } = require('./logic.js');

test('AC1: yeniOyun() 9 elemanlı ve tüm elemanları null olan bir tahta döner', () => {
  const tahta = yeniOyun();
  assert.strictEqual(tahta.length, 9);
  assert.ok(tahta.every((hucre) => hucre === null));
});

test('AC2: boş bir hücreye hamle yapıldığında hamleYap() true döner ve değer atanır', () => {
  const tahta = yeniOyun();
  const sonuc = hamleYap(tahta, 4, 'X');
  assert.strictEqual(sonuc, true);
  assert.strictEqual(tahta[4], 'X');
});

test('AC3: dolu bir hücreye hamle yapılmaya çalışıldığında hamleYap() tahtayı değiştirmeden false döner', () => {
  const tahta = yeniOyun();
  hamleYap(tahta, 0, 'X');
  const oncekiTahta = [...tahta];
  const sonuc = hamleYap(tahta, 0, 'O');
  assert.strictEqual(sonuc, false);
  assert.deepStrictEqual(tahta, oncekiTahta);
});

test('AC3b: geçersiz indekse hamle yapılmaya çalışıldığında hamleYap() false döner', () => {
  const tahta = yeniOyun();
  const sonuc = hamleYap(tahta, 9, 'X');
  assert.strictEqual(sonuc, false);
  assert.ok(tahta.every((hucre) => hucre === null));
});

test('AC4: boş tahtada siradakiOyuncu() X döner', () => {
  const tahta = yeniOyun();
  assert.strictEqual(siradakiOyuncu(tahta), 'X');
});

test('AC4b: tek hamle yapılmış tahtada siradakiOyuncu() O döner', () => {
  const tahta = yeniOyun();
  hamleYap(tahta, 0, 'X');
  assert.strictEqual(siradakiOyuncu(tahta), 'O');
});

test('AC5: yatay üç aynı işaret gelince kazanan() o işareti döndürür', () => {
  const tahta = ['X', 'X', 'X', null, null, null, null, null, null];
  assert.strictEqual(kazanan(tahta), 'X');
});

test('AC5b: dikey üç aynı işaret gelince kazanan() o işareti döndürür', () => {
  const tahta = ['O', null, null, 'O', null, null, 'O', null, null];
  assert.strictEqual(kazanan(tahta), 'O');
});

test('AC5c: çapraz üç aynı işaret gelince kazanan() o işareti döndürür', () => {
  const tahta = ['X', null, null, null, 'X', null, null, null, 'X'];
  assert.strictEqual(kazanan(tahta), 'X');
});

test('AC6: kazanan dizilim bulunmayan bir tahtada kazanan() null döner', () => {
  const tahta = ['X', 'O', 'X', 'X', 'O', 'O', 'O', 'X', 'X'];
  assert.strictEqual(kazanan(tahta), null);
});

test('AC7: tahta tamamen doluyken kazanan yoksa beraberlikMi() true döner', () => {
  const tahta = ['X', 'O', 'X', 'X', 'O', 'O', 'O', 'X', 'X'];
  assert.strictEqual(kazanan(tahta), null);
  assert.strictEqual(beraberlikMi(tahta), true);
});

test('AC8: kazanan bulunan dolu bir tahtada beraberlikMi() false döner', () => {
  const tahta = ['X', 'X', 'X', 'O', 'O', 'X', 'X', 'O', 'O'];
  assert.strictEqual(kazanan(tahta), 'X');
  assert.strictEqual(beraberlikMi(tahta), false);
});

